#!/usr/bin/env python3
"""Tests for strip_attribution.py. No dependencies: plain unittest.

    python3 .github/scripts/test_strip_attribution.py
"""

from __future__ import annotations

import unittest

import strip_attribution as strip


class IsAttributionTest(unittest.TestCase):
    """One line at a time: what counts as attribution, and what must survive."""

    ATTRIBUTION = [
        "🤖 Generated with [Arena.ai Agent Mode](https://arena.ai)",
        "🤖 Generated with [Arena.ai](https://arena.ai)",
        "🤖 Generated with Arena.ai agent mode",
        "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
        "Generated with Arena Agent Mode",
        "Made with Arena.ai",
        "Generated by Arena Agent Mode",
        "Co-Authored-By: arena-agent <297053741+arena-agent@users.noreply.github.com>",
        "Co-Authored-By: Claude <noreply@anthropic.com>",
        "<!-- generated by an AI agent, do not edit -->",
        "This PR was opened by an AI agent",
        "Built by an AI agent",
        "Assisted by a bot",
        "Powered by an AI agent",
    ]

    PROSE = [
        # "arena" is an ordinary word in this repository (the arena/... branches).
        "- Every commit was made with `--no-verify`, so none carries an Arena trailer.",
        "- Run `git checkout arena/911b8859-riverguard-dev` first.",
        "The arena/ branches are named after sessions.",
        # Mentions of tools and sources that are not attribution.
        "- Generated with `python data/generate_dataset.py`",
        "Rainfall comes from Open-Meteo ERA5",
        "Assisted by the Marikina MDRRMO",
        "Powered by the MapLibre raster basemap",
        "",
        "## Verification",
    ]

    def test_attribution_lines_are_detected(self) -> None:
        for line in self.ATTRIBUTION:
            with self.subTest(line=line):
                self.assertTrue(strip.is_attribution(line))

    def test_prose_survives(self) -> None:
        for line in self.PROSE:
            with self.subTest(line=line):
                self.assertFalse(strip.is_attribution(line))

    def test_quoted_trailer_inside_code_span_survives(self) -> None:
        line = "Hook output: `Co-Authored-By: Claude <noreply@anthropic.com>`"
        self.assertFalse(strip.is_attribution(line))


class CleanTest(unittest.TestCase):
    def test_removes_footer_and_leftover_separator(self) -> None:
        body = "## Summary\n\nReal text.\n\n---\n\n🤖 Generated with [Arena.ai](https://arena.ai)\n"
        cleaned, removed = strip.clean(body)
        self.assertEqual(["🤖 Generated with [Arena.ai](https://arena.ai)"], removed)
        self.assertEqual("## Summary\n\nReal text.\n", cleaned)

    def test_body_without_attribution_is_untouched(self) -> None:
        body = "## Summary\n\nReal text.\n"
        cleaned, removed = strip.clean(body)
        self.assertEqual([], removed)
        self.assertEqual(body, cleaned)

    def test_fenced_code_keeps_footer_like_lines(self) -> None:
        body = "Example:\n\n```\n🤖 Generated with Claude Code\n```\n"
        cleaned, removed = strip.clean(body)
        self.assertEqual([], removed)
        self.assertIn("🤖 Generated with Claude Code", cleaned)

    def test_clean_is_idempotent(self) -> None:
        body = "Text.\n\n🤖 Generated with Arena.ai agent mode\n"
        once, _ = strip.clean(body)
        twice, removed = strip.clean(once)
        self.assertEqual(once, twice)
        self.assertEqual([], removed)

    def test_everything_is_attribution_yields_empty_body(self) -> None:
        cleaned, removed = strip.clean("🤖 Generated with Arena.ai Agent Mode\n")
        self.assertEqual(1, len(removed))
        self.assertEqual("", cleaned)


class MainTest(unittest.TestCase):
    def test_check_mode_and_clean_mode(self) -> None:
        import io
        import os
        import sys
        import tempfile

        with tempfile.NamedTemporaryFile("w", suffix=".md", delete=False) as handle:
            handle.write("Real text.\n\n🤖 Generated with Arena.ai\n")
            dirty = handle.name

        stderr, stdout = sys.stderr, sys.stdout
        try:
            sys.stderr, sys.stdout = io.StringIO(), io.StringIO()
            self.assertEqual(1, strip.main(["strip_attribution.py", "--check", dirty]))
            sys.stderr, sys.stdout = io.StringIO(), io.StringIO()
            self.assertEqual(0, strip.main(["strip_attribution.py", dirty]))
            self.assertEqual("Real text.\n", sys.stdout.getvalue())
        finally:
            sys.stderr, sys.stdout = stderr, stdout
            os.unlink(dirty)


if __name__ == "__main__":
    unittest.main(verbosity=2)
